def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n >= 99:
        return 'D'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    my_defects = sum(1 for x in my if x == 'D')
    op_defects = sum(1 for x in op if x == 'D')
    last_op = op[-1]
    last_my = my[-1]

    # Pure cooperator: exploit only in the last couple rounds.
    if op_defects == 0:
        return 'D' if n >= 98 else 'C'

    # Detect TFT-like: opponent mirrors our previous action.
    if n >= 4:
        matches = 0
        total = n - 1
        for i in range(1, n):
            if op[i] == my[i - 1]:
                matches += 1
        if matches * 10 >= total * 8:
            return 'C'

    # Opponent recently very defection-heavy: punish.
    recent = op[-8:]
    rdef = sum(1 for x in recent if x == 'D')
    if rdef >= 6:
        return 'D'
    if rdef >= 4 and last_op == 'D':
        return 'D'

    # If we have been defecting too much, return to cooperation to avoid spiral.
    if last_my == 'D' and last_op == 'C':
        return 'C'

    # Cooperate mostly; retaliate immediately on defection, forgive quickly.
    if last_op == 'D':
        # forgive if opponent cooperated in most of the recent window
        if rdef <= 2:
            return 'C'
        return 'D'

    # Last opp was C: stay cooperative, with a rare probe if opponent is very nice.
    if op_defects * 8 < n and n >= 20 and n % 13 == 7:
        return 'D'
    return 'C'
